def solve(grid):
    if not grid:
        return []
    h = len(grid)
    w = len(grid[0])

    # Collect cells by color
    from collections import defaultdict
    color_cells = defaultdict(list)
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != 0:
                color_cells[val].append((r, c))

    # Find 8-connected components for each color
    components = []  # list of (color, set_of_cells)
    for color, cells in color_cells.items():
        cell_set = set(cells)
        visited = set()
        for cell in cells:
            if cell in visited:
                continue
            stack = [cell]
            comp = set()
            while stack:
                r, c = stack.pop()
                if (r, c) in visited:
                    continue
                visited.add((r, c))
                comp.add((r, c))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            nxt = (nr, nc)
                            if nxt in cell_set and nxt not in visited:
                                stack.append(nxt)
            components.append((color, comp))

    # Group components by color
    color_comps = defaultdict(list)
    for color, comp in components:
        color_comps[color].append(comp)

    out = [[0] * w for _ in range(h)]

    # For each pair of components of the same color, draw a line if they share a row or column
    for color, comps in color_comps.items():
        n = len(comps)
        for i in range(n):
            for j in range(i + 1, n):
                c1 = comps[i]
                c2 = comps[j]

                # Check shared rows (horizontal potential)
                rows1 = set(r for r, _ in c1)
                rows2 = set(r for r, _ in c2)
                best_row = None
                best_row_gap = float('inf')
                row_left = None
                row_right = None

                for r in rows1 & rows2:
                    cols1 = [c for rr, c in c1 if rr == r]
                    cols2 = [c for rr, c in c2 if rr == r]
                    for cc1 in cols1:
                        for cc2 in cols2:
                            if cc1 == cc2:
                                continue
                            gap = abs(cc1 - cc2) - 1
                            if gap < best_row_gap:
                                best_row_gap = gap
                                best_row = r
                                row_left = min(cc1, cc2)
                                row_right = max(cc1, cc2)

                # Check shared columns (vertical potential)
                cols1s = set(c for _, c in c1)
                cols2s = set(c for _, c in c2)
                best_col = None
                best_col_gap = float('inf')
                col_top = None
                col_bottom = None

                for c in cols1s & cols2s:
                    rows1c = [r for r, cc in c1 if cc == c]
                    rows2c = [r for r, cc in c2 if cc == c]
                    for rr1 in rows1c:
                        for rr2 in rows2c:
                            if rr1 == rr2:
                                continue
                            gap = abs(rr1 - rr2) - 1
                            if gap < best_col_gap:
                                best_col_gap = gap
                                best_col = c
                                col_top = min(rr1, rr2)
                                col_bottom = max(rr1, rr2)

                # Choose direction with smaller gap; tie -> vertical
                if best_row is not None and best_col is not None:
                    if best_row_gap <= best_col_gap:
                        # draw horizontal
                        for c in range(row_left + 1, row_right):
